import { describe, expect, test } from 'bun:test'

import { selectedSitePackageAdmin } from '../src/admin'
import {
  estimateCalculatorDataSchema,
  selectedBlockDefinitions,
  selectedPageDraftSchema,
  selectedSitePackageDescriptor,
} from '../src/contract'

const validCalculatorData = {
  title: 'Рассчитайте стоимость',
  description: 'Предварительный расчёт',
  unitPrice: 1_800,
  minimumPrice: 15_000,
  minimumArea: 5,
  maximumArea: 300,
}

describe('estimateCalculator contract', () => {
  test('accepts all CMS-editable calculator parameters and rejects unknown data', () => {
    expect(estimateCalculatorDataSchema.parse(validCalculatorData)).toEqual(validCalculatorData)
    expect(() => estimateCalculatorDataSchema.parse({
      ...validCalculatorData,
      formula: 'area * unitPrice',
    })).toThrow()
  })

  test('rejects invalid price and area bounds', () => {
    expect(() => estimateCalculatorDataSchema.parse({
      ...validCalculatorData,
      unitPrice: -1,
    })).toThrow()
    expect(() => estimateCalculatorDataSchema.parse({
      ...validCalculatorData,
      maximumArea: 4,
    })).toThrow()
  })

  test('registers a descriptor-driven editor for every editable field', () => {
    const definition = selectedBlockDefinitions.find(({ type }) => type === 'estimateCalculator')

    expect(selectedSitePackageDescriptor).toEqual({
      id: 'reference-calculator',
      version: '1.0.0',
      schemaVersion: 1,
    })
    expect(definition?.editor.kind).toBe('descriptor')
    expect(definition?.editor.fields.map(({ key }) => key)).toEqual([
      'title',
      'description',
      'unitPrice',
      'minimumPrice',
      'minimumArea',
      'maximumArea',
    ])
    expect(selectedSitePackageAdmin.customEditors).toEqual({})
  })

  test('validates calculator blocks in page drafts', () => {
    const draft = selectedPageDraftSchema.parse({
      title: 'Калькулятор ремонта',
      path: '/calculator',
      seo: {
        title: 'Расчёт стоимости ремонта',
        description: 'Рассчитайте предварительную стоимость работ по площади.',
        canonicalMode: 'self',
        noIndex: true,
      },
      blocks: [{ id: 'calculator', type: 'estimateCalculator', data: validCalculatorData }],
      expectedRevision: 0,
    })

    expect(draft.blocks[0]).toEqual({
      id: 'calculator',
      type: 'estimateCalculator',
      data: validCalculatorData,
    })
  })
})
